{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Nilotinib, a high-transfer aminopyrimidine-aniline kinase inhibitor, has 31% absolute oral bioavailability in fasted humans, directly supporting F >= 20% for the query's similar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "GSK1322322, sharing the aniline-aminopyrimidine, methoxy, and basic amine features, showed 77% absolute oral bioavailability in fed healthy volunteers (57% fasted), strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Amiodarone, a lipophilic basic amine with high molecular weight and variable absorption, had mean absolute F of 65% (range 22-104%), showing that such physicochemical features can still meet F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Encainide, with aniline/methoxy/basic amine features, had mean absolute F of 32 ± 7% in normal subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "R101933, a large basic P-gp inhibitor, had low oral bioavailability with high variability, providing some contradictory evidence for large ionizable molecules.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C36"],
      "claim": "Alprenolol, a small basic beta-blocker, had absolute F ≈ 10% due to first-pass metabolism; this low-F mechanism is weakly transferable to the larger query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Remimazolam had very low absolute F (1.2%) due to ester hydrolysis; the query lacks an ester, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Avoralstat, an oral kallikrein inhibitor with amide/methoxy and ionizable groups, had low oral bioavailability, providing some contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Prothipendyl had low absolute bioavailability after a single dose, but its tricyclic phenothiazine structure is less similar to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer analogues with closely related aminopyrimidine-aniline and basic amine scaffolds (nilotinib, GSK1322322) show absolute F of 31% and 57-77%, strongly supporting F >= 20%. Lower-transfer low-F molecules are mechanistically distinct (first-pass metabolism, ester hydrolysis, tricyclic phenothiazine) and less applicable. The physicochemical low-F prior is uncertain and outweighed by direct analogue data.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "Acrylamide warhead reactivity and metabolic stability are unknown.",
    "No data on efflux/transporter effects or P-gp liability.",
    "No solubility/dissolution or formulation/dose dependence data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

